package com.ruoyi.fund.controller;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.core.web.controller.BaseController; import com.ruoyi.common.core.web.domain.AjaxResult; import com.ruoyi.common.core.web.page.TableDataInfo; import com.ruoyi.common.log.annotation.Log; import com.ruoyi.common.log.enums.BusinessType; import com.ruoyi.common.security.annotation.RequiresPermissions; import com.ruoyi.fund.domain.FundProjectBudget; import com.ruoyi.fund.service.IFundBudgetService;
@RestController @RequestMapping("/budget") public class FundBudgetController extends BaseController { @Autowired private IFundBudgetService service; @RequiresPermissions("fund:budget:list") @GetMapping("/list") public TableDataInfo list(FundProjectBudget q){startPage();List<FundProjectBudget> l=service.selectList(q);return getDataTable(l);} @GetMapping("/topic/{topicId}") public AjaxResult byTopic(@PathVariable Long topicId){return AjaxResult.success(service.selectByTopicId(topicId));} @RequiresPermissions("fund:budget:add") @Log(title="课题总资金",businessType=BusinessType.INSERT) @PostMapping public AjaxResult add(@Validated @RequestBody FundProjectBudget b){return toAjax(service.insert(b));} @RequiresPermissions("fund:budget:edit") @Log(title="课题总资金",businessType=BusinessType.UPDATE) @PutMapping public AjaxResult edit(@Validated @RequestBody FundProjectBudget b){return toAjax(service.update(b));} @RequiresPermissions("fund:budget:remove") @Log(title="课题总资金",businessType=BusinessType.DELETE) @DeleteMapping("/{id}") public AjaxResult del(@PathVariable Long id){return toAjax(service.delete(id));} }
